// Hyperliquid public market data. Separate from the own-node output adapter.
// Exact provider candles remain authoritative; trades never masquerade as Solana fills.
#include <curl/curl.h>
#include <curl/websockets.h>
#include <sqlite3.h>
#include <nlohmann/json.hpp>
#include <zstd.h>
#include <atomic>
#include <chrono>
#include <condition_variable>
#include <csignal>
#include <deque>
#include <filesystem>
#include <fstream>
#include <iostream>
#include <mutex>
#include <poll.h>
#include <set>
#include <thread>
#include <cmath>
#include <charconv>
using J=nlohmann::json;using Clock=std::chrono::steady_clock;
std::atomic<bool> run{true};void stop(int){run=false;}
int64_t ms(){return std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::system_clock::now().time_since_epoch()).count();}
void pause_ms(int n){for(int i=0;i<n&&run;i+=100)std::this_thread::sleep_for(std::chrono::milliseconds(std::min(100,n-i)));}
void require(bool b,const char*s){if(!b)throw std::runtime_error(s);}
void sql(sqlite3*d,const char*s){char*e=nullptr;if(sqlite3_exec(d,s,nullptr,nullptr,&e)!=SQLITE_OK){std::string x=e?e:"SQL failure";sqlite3_free(e);throw std::runtime_error(x);}}
struct St{sqlite3*d;sqlite3_stmt*s=nullptr;St(sqlite3*x,const char*q):d(x){require(sqlite3_prepare_v2(d,q,-1,&s,nullptr)==SQLITE_OK,sqlite3_errmsg(d));}~St(){sqlite3_finalize(s);}void text(int n,const std::string&v){sqlite3_bind_text(s,n,v.c_str(),v.size(),SQLITE_TRANSIENT);}void integer(int n,int64_t v){sqlite3_bind_int64(s,n,v);}void real(int n,double v){sqlite3_bind_double(s,n,v);}void done(){require(sqlite3_step(s)==SQLITE_DONE,sqlite3_errmsg(d));}bool row(){int r=sqlite3_step(s);require(r==SQLITE_ROW||r==SQLITE_DONE,sqlite3_errmsg(d));return r==SQLITE_ROW;}std::string str(int n){auto*p=sqlite3_column_text(s,n);return p?(const char*)p:"";}};
size_t receive(char*p,size_t a,size_t b,void*ctx){auto&s=*(std::string*)ctx;size_t n=a*b;if(s.size()+n>16*1024*1024)return 0;s.append(p,n);return n;}
// One REST worker per process. Worst-case candle weight is reserved before each read.
J post(const J&body,int weight=20){static auto next=Clock::now();while(run&&Clock::now()<next)pause_ms(100);require(run,"Stopped");auto start=Clock::now();next=start+std::chrono::milliseconds(weight*75);CURL*c=curl_easy_init();require(c,"curl allocation");std::string bytes,request=body.dump();curl_slist*h=curl_slist_append(nullptr,"Content-Type: application/json");curl_easy_setopt(c,CURLOPT_URL,"https://api.hyperliquid.xyz/info");curl_easy_setopt(c,CURLOPT_HTTPHEADER,h);curl_easy_setopt(c,CURLOPT_POSTFIELDS,request.c_str());curl_easy_setopt(c,CURLOPT_WRITEFUNCTION,receive);curl_easy_setopt(c,CURLOPT_WRITEDATA,&bytes);curl_easy_setopt(c,CURLOPT_CONNECTTIMEOUT,10L);curl_easy_setopt(c,CURLOPT_TIMEOUT,25L);curl_easy_setopt(c,CURLOPT_USERAGENT,"Ticking-Hyperliquid/1");auto e=curl_easy_perform(c);long status=0;curl_easy_getinfo(c,CURLINFO_RESPONSE_CODE,&status);curl_slist_free_all(h);curl_easy_cleanup(c);if(status==429)next=Clock::now()+std::chrono::seconds(60);require(e==CURLE_OK&&status==200,"Hyperliquid REST unavailable");return J::parse(bytes);}
double decimal(const J&v){double x=0;if(v.is_string()){auto&s=v.get_ref<const std::string&>();require(!s.empty()&&s.size()<80,"decimal bound");auto r=std::from_chars(s.data(),s.data()+s.size(),x);require(r.ec==std::errc{}&&r.ptr==s.data()+s.size(),"invalid decimal");}else{require(v.is_number(),"invalid number");x=v.get<double>();}require(std::isfinite(x)&&x>=0,"nonfinite or negative");return x;}
const std::map<std::string,int64_t> periods={{"1m",60000},{"3m",180000},{"5m",300000},{"15m",900000},{"30m",1800000},{"1h",3600000},{"2h",7200000},{"4h",14400000},{"8h",28800000},{"12h",43200000},{"1d",86400000},{"3d",259200000},{"1w",604800000}};
J discover(int count){J raw=J::array(),markets=J::array();auto spot=post({{"type","spotMeta"}});std::map<int,std::string> tokens;for(auto&t:spot.at("tokens"))tokens[t.at("index").get<int>()]=t.at("name");auto dex=post({{"type","perpDexs"}});std::vector<std::string> names{""};for(auto&d:dex)if(d.is_object())names.push_back(d.at("name"));require(names.size()<=32,"DEX discovery bound");for(auto&name:names){auto result=post({{"type","metaAndAssetCtxs"},{"dex",name}});raw.push_back({{"dex",name},{"data",result}});auto&meta=result.at(0);auto&ctx=result.at(1);auto&u=meta.at("universe");require(u.size()==ctx.size()&&u.size()<=2000,"metadata identity count");int collateral=meta.value("collateralToken",0);require(tokens.count(collateral),"unknown collateral token");for(size_t i=0;i<u.size();i++){auto&a=u[i];auto&v=ctx[i];std::string coin=a.at("name");if(a.value("isDelisted",false)||coin.empty()||coin.size()>40)continue;require(name.empty()?coin.find(':')==std::string::npos:coin.starts_with(name+":"),"DEX namespace mismatch");double volume=decimal(v.at("dayNtlVlm")),price=decimal(v.at("markPx"));if(volume<=0||price<=0)continue;std::string base=coin.substr(coin.find(':')==std::string::npos?0:coin.find(':')+1);markets.push_back({{"id","HL-"+coin},{"symbol",coin},{"name",coin+" perpetual"},{"network","exchange"},{"marketType","perpetual"},{"source","hyperliquid_public"},{"venue","Hyperliquid"},{"market",coin},{"base",base},{"quote",tokens[collateral]},{"mint",nullptr},{"dex",name},{"category",name.empty()?"Hyperliquid crypto":"Hyperliquid HIP-3"},{"icon",nullptr},{"price",price},{"selectionVolume",volume},{"context",v},{"reviewed_at",ms()/1000},{"verification",{{"status","reviewed"},{"id","HL-"+coin},{"mint",nullptr},{"basis","provider_instrument_identity"},{"scope","Hyperliquid perpetual identity, not the underlying security or a Solana mint."}}}});}}
std::sort(markets.begin(),markets.end(),[](auto&a,auto&b){return a["selectionVolume"].template get<double>()>b["selectionVolume"].template get<double>();});J selected=J::array();for(int i=0;i<std::min(count,(int)markets.size());i++)selected.push_back(markets[i]);return {{"version",1},{"source","hyperliquid_public"},{"at",ms()},{"discovered",markets},{"markets",selected},{"raw",raw},{"spotMeta",spot}};}
sqlite3* database(const std::string&path){std::filesystem::create_directories(std::filesystem::path(path).parent_path());sqlite3*d=nullptr;require(sqlite3_open(path.c_str(),&d)==SQLITE_OK,"database open");sqlite3_busy_timeout(d,5000);sql(d,R"SQL(PRAGMA journal_mode=WAL;PRAGMA synchronous=FULL;
CREATE TABLE IF NOT EXISTS markets(coin TEXT PRIMARY KEY,identity TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS candles(coin TEXT,period TEXT,time INTEGER,end INTEGER,o REAL,h REAL,l REAL,c REAL,v REAL,n INTEGER,received INTEGER,kind TEXT,PRIMARY KEY(coin,period,time)) WITHOUT ROWID;
CREATE TABLE IF NOT EXISTS trades(coin TEXT,time INTEGER,tid INTEGER,price REAL,size REAL,side TEXT,hash TEXT,received INTEGER,PRIMARY KEY(coin,time,tid)) WITHOUT ROWID;
CREATE TABLE IF NOT EXISTS books(coin TEXT PRIMARY KEY,time INTEGER,payload TEXT,received INTEGER);
CREATE TABLE IF NOT EXISTS originals(id INTEGER PRIMARY KEY,channel TEXT,received INTEGER,raw BLOB NOT NULL);
CREATE TABLE IF NOT EXISTS jobs(coin TEXT,period TEXT,depth INTEGER,done INTEGER,first INTEGER,last INTEGER,rows INTEGER,PRIMARY KEY(coin,period,depth)) WITHOUT ROWID;
CREATE TABLE IF NOT EXISTS events(id INTEGER PRIMARY KEY,time INTEGER,kind TEXT,detail TEXT);
CREATE TABLE IF NOT EXISTS state(id INTEGER PRIMARY KEY,revision INTEGER,updated INTEGER);
INSERT OR IGNORE INTO state VALUES(1,0,0);
)SQL");return d;}
void event(sqlite3*d,const std::string&kind,const std::string&detail){St s(d,"INSERT INTO events(time,kind,detail) VALUES(?,?,?)");s.integer(1,ms());s.text(2,kind);s.text(3,detail);s.done();}
struct Frame{std::string kind,coin,period;J data;int64_t received;int depth=0;};std::mutex mutex;std::condition_variable ready;std::deque<Frame> queue;size_t queuedBytes=0;std::atomic<int64_t> frames{0},accepted{0},invalid{0},reconnects{0};
void push(Frame x){size_t bytes=x.data.dump().size();require(bytes<=16*1024*1024,"frame bound");std::unique_lock lock(mutex);ready.wait(lock,[&]{return !run||(queue.size()<512&&queuedBytes+bytes<32*1024*1024);});if(!run)return;queuedBytes+=bytes;queue.push_back(std::move(x));ready.notify_all();}
void retain(sqlite3*d,const Frame&f){std::string raw=f.data.dump();std::vector<char> compressed(ZSTD_compressBound(raw.size()));size_t n=ZSTD_compress(compressed.data(),compressed.size(),raw.data(),raw.size(),3);require(!ZSTD_isError(n),"compress failed");St s(d,"INSERT INTO originals(channel,received,raw) VALUES(?,?,?)");s.text(1,f.kind);s.integer(2,f.received);sqlite3_bind_blob(s.s,3,compressed.data(),n,SQLITE_TRANSIENT);s.done();}
void candle(sqlite3*d,const J&b,const Frame&f,const std::set<std::string>&allowed){std::string coin=b.at("s"),period=b.at("i");require(allowed.count(coin)&&periods.count(period),"unadmitted candle");if(f.kind=="rest")require(coin==f.coin&&period==f.period,"history identity mismatch");int64_t t=b.at("t"),end=b.at("T"),step=periods.at(period),n=b.at("n");int64_t shift=0; // Provider intervals, including weeks, are Unix-epoch anchored.
require(t>1500000000000&&t<=f.received+60000&&(t-shift)%step==0&&end==t+step-1&&n>=0,"candle time/count invalid");double o=decimal(b.at("o")),h=decimal(b.at("h")),l=decimal(b.at("l")),c=decimal(b.at("c")),v=decimal(b.at("v"));require(l>0&&l<=std::min(o,c)&&h>=std::max(o,c),"candle range invalid");St s(d,"INSERT INTO candles VALUES(?,?,?,?,?,?,?,?,?,?,?,?) ON CONFLICT(coin,period,time) DO UPDATE SET end=excluded.end,o=excluded.o,h=excluded.h,l=excluded.l,c=excluded.c,v=excluded.v,n=excluded.n,received=excluded.received,kind=excluded.kind WHERE excluded.received>=candles.received AND (excluded.n>=candles.n OR (excluded.kind='rest' AND excluded.end<excluded.received-60000))");s.text(1,coin);s.text(2,period);s.integer(3,t);s.integer(4,end);s.real(5,o);s.real(6,h);s.real(7,l);s.real(8,c);s.real(9,v);s.integer(10,n);s.integer(11,f.received);s.text(12,f.kind);s.done();}
void apply(sqlite3*d,const Frame&f,const std::set<std::string>&allowed){if(f.kind=="event"){event(d,f.coin,f.data.dump());return;}sql(d,"SAVEPOINT frame");try{
if(f.kind=="rest"||f.kind=="candle"){auto rows=f.data.is_array()?f.data:J::array({f.data});require(rows.size()<=5001,"candle page bound");for(auto&b:rows)candle(d,b,f,allowed);if(f.kind=="rest"){St s(d,"INSERT INTO jobs VALUES(?,?,?,?,?,?,?) ON CONFLICT(coin,period,depth) DO UPDATE SET done=excluded.done,first=excluded.first,last=excluded.last,rows=excluded.rows");s.text(1,f.coin);s.text(2,f.period);s.integer(3,f.depth);s.integer(4,f.received);s.integer(5,rows.empty()?0:rows.front().at("t").get<int64_t>());s.integer(6,rows.empty()?0:rows.back().at("t").get<int64_t>());s.integer(7,rows.size());s.done();}}
else if(f.kind=="trades"){require(f.data.is_array()&&f.data.size()<=20000,"trade batch bound");for(auto&t:f.data){std::string coin=t.at("coin"),side=t.at("side"),hash=t.at("hash");int64_t stamp=t.at("time"),tid=t.at("tid");double price=decimal(t.at("px")),size=decimal(t.at("sz"));require(allowed.count(coin)&&(side=="A"||side=="B")&&stamp>1500000000000&&stamp<=f.received+60000&&tid>=0&&tid<(1ll<<53)&&price>0&&size>0&&hash.size()<=80,"trade identity/value invalid");St old(d,"SELECT price,size,side,hash FROM trades WHERE coin=? AND time=? AND tid=?");old.text(1,coin);old.integer(2,stamp);old.integer(3,tid);if(old.row()){require(sqlite3_column_double(old.s,0)==price&&sqlite3_column_double(old.s,1)==size&&old.str(2)==side&&old.str(3)==hash,"conflicting trade identity");continue;}St s(d,"INSERT INTO trades VALUES(?,?,?,?,?,?,?,?)");s.text(1,coin);s.integer(2,stamp);s.integer(3,tid);s.real(4,price);s.real(5,size);s.text(6,side);s.text(7,hash);s.integer(8,f.received);s.done();}}
else if(f.kind=="l2Book"){auto&b=f.data;std::string coin=b.at("coin");int64_t t=b.at("time");auto&levels=b.at("levels");require(allowed.count(coin)&&t>1500000000000&&t<=f.received+60000&&levels.size()==2,"book identity invalid");double bid=0,ask=0;for(int side=0;side<2;side++){require(levels[side].size()<=20,"book depth");double previous=side==0?INFINITY:0;for(auto&l:levels[side]){double p=decimal(l.at("px")),sz=decimal(l.at("sz"));require(p>0&&sz>0&&l.at("n").get<int64_t>()>0&&(side==0?p<previous:p>previous),"book order invalid");previous=p;}if(!levels[side].empty())(side==0?bid:ask)=decimal(levels[side][0]["px"]);}require(!bid||!ask||bid<ask,"crossed book");St s(d,"INSERT INTO books VALUES(?,?,?,?) ON CONFLICT(coin) DO UPDATE SET time=excluded.time,payload=excluded.payload,received=excluded.received WHERE excluded.time>books.time");s.text(1,coin);s.integer(2,t);s.text(3,b.dump());s.integer(4,f.received);s.done();}
else throw std::runtime_error("unrecognized frame");retain(d,f);sql(d,"RELEASE frame");accepted++;}catch(const std::exception&e){sql(d,"ROLLBACK TO frame; RELEASE frame");retain(d,f);event(d,"rejected",e.what());invalid++;}}
bool send(CURL*c,const J&j){static std::mutex gate;static auto next=Clock::now();{std::unique_lock lock(gate);while(run&&Clock::now()<next)pause_ms(10);next=Clock::now()+std::chrono::milliseconds(45);}if(!run)return false;std::string s=j.dump();size_t n=0;auto rc=curl_ws_send(c,s.data(),s.size(),&n,0,CURLWS_TEXT);return rc==CURLE_OK&&n==s.size();}
void websocket(std::vector<std::string> coins,int shard){int retry=1;while(run){CURL*c=curl_easy_init();curl_easy_setopt(c,CURLOPT_URL,"wss://api.hyperliquid.xyz/ws");curl_easy_setopt(c,CURLOPT_CONNECT_ONLY,2L);curl_easy_setopt(c,CURLOPT_CONNECTTIMEOUT,10L);curl_easy_setopt(c,CURLOPT_TIMEOUT,15L);if(curl_easy_perform(c)==CURLE_OK){bool okay=true;for(auto&coin:coins){for(auto&i:{"1m","1h","1d"}){okay=okay&&send(c,{{"method","subscribe"},{"subscription",{{"type","candle"},{"coin",coin},{"interval",i}}}});pause_ms(40);}for(auto&k:{"trades","l2Book"}){okay=okay&&send(c,{{"method","subscribe"},{"subscription",{{"type",k},{"coin",coin}}}});pause_ms(40);}}curl_socket_t sock;curl_easy_getinfo(c,CURLINFO_ACTIVESOCKET,&sock);std::string message;auto last=Clock::now(),ping=last;retry=1;while(run&&okay&&Clock::now()-last<std::chrono::seconds(60)){if(Clock::now()-ping>std::chrono::seconds(20)){okay=send(c,{{"method","ping"}});ping=Clock::now();}char buffer[65536];size_t n=0;const curl_ws_frame*meta=nullptr;auto result=curl_ws_recv(c,buffer,sizeof buffer,&n,&meta);if(result==CURLE_AGAIN){pollfd fd{sock,POLLIN,0};poll(&fd,1,50);continue;}if(result!=CURLE_OK||!meta||meta->flags&CURLWS_CLOSE)break;last=Clock::now();if(!(meta->flags&(CURLWS_TEXT|CURLWS_CONT)))continue;message.append(buffer,n);if(message.size()>4*1024*1024)break;if(meta->bytesleft||meta->flags&CURLWS_CONT)continue;try{auto j=J::parse(message);std::string kind=j.value("channel","");if(kind=="candle"||kind=="trades"||kind=="l2Book"){push({kind,"","",j.at("data"),ms()});frames++;}else if(kind=="error"){push({"event","upstream_error","",j,ms()});okay=false;}}catch(const J::exception&){invalid++;}message.clear();}}curl_easy_cleanup(c);reconnects++;push({"event","disconnect","",{{"shard",shard},{"at",ms()},{"recovery","Reconnect gap remains unverified; external history service required"}},ms()});pause_ms(retry*1000+shard*100);retry=std::min(60,retry*2);}}
// Bulk and recent REST candle backfill are intentionally excluded from this public live collector.
int main(int argc,char**argv){signal(SIGINT,stop);signal(SIGTERM,stop);curl_global_init(CURL_GLOBAL_DEFAULT);std::vector<std::thread> threads;sqlite3*d=nullptr;try{require(argc>=4,"usage: discover catalog count | live catalog db | fixture catalog db jsonl");std::string mode=argv[1];if(mode=="discover"){int n=std::stoi(argv[3]);require(n>=1&&n<=180,"admission max 180 instruments / 900 subscriptions");auto j=discover(n);std::ofstream f(std::string(argv[2])+".tmp");f<<j.dump();f.close();std::filesystem::rename(std::string(argv[2])+".tmp",argv[2]);std::cout<<J{{"discovered",j["discovered"].size()},{"selected",j["markets"].size()}}<<std::endl;return 0;}
std::ifstream file(argv[2]);auto catalog=J::parse(file);require(catalog["source"]=="hyperliquid_public"&&catalog["markets"].size()<=180,"catalog contract");d=database(argv[3]);std::set<std::string> allowed;std::vector<std::string> coins;for(auto&m:catalog["markets"]){std::string coin=m.at("market");require(allowed.insert(coin).second,"duplicate market");coins.push_back(coin);St old(d,"SELECT identity FROM markets WHERE coin=?");old.text(1,coin);if(old.row()){auto a=J::parse(old.str(0));for(auto k:{"id","source","marketType","base","quote","dex"})require(a[k]==m[k],"catalog identity changed");}St s(d,"INSERT INTO markets VALUES(?,?) ON CONFLICT(coin) DO UPDATE SET identity=excluded.identity");s.text(1,coin);s.text(2,m.dump());s.done();}
if(mode=="fixture"){require(argc==5,"fixture file required");std::ifstream in(argv[4]);std::string line;while(std::getline(in,line)){auto f=J::parse(line);apply(d,{f.at("kind"),f.value("coin",""),f.value("period",""),f.at("data"),f.value("received",ms()),f.value("depth",0)},allowed);}std::cout<<J{{"accepted",accepted.load()},{"invalid",invalid.load()}}<<std::endl;sqlite3_close(d);return 0;}
require(mode=="live","unknown mode");event(d,"start","Public feed; not a HyperCore node. Reconnect trade completeness unverified.");for(size_t i=0;i<coins.size();i+=30){threads.emplace_back(websocket,std::vector<std::string>(coins.begin()+i,coins.begin()+std::min(i+30,coins.size())),i/30);pause_ms(200);}
auto report=Clock::now();double maxCommit=0;for(;;){std::deque<Frame> batch;{std::unique_lock lock(mutex);ready.wait_for(lock,std::chrono::milliseconds(50),[]{return !queue.empty()||!run;});if(queue.empty()&&!run)break;for(int i=0;i<64&&!queue.empty();i++){queuedBytes-=queue.front().data.dump().size();batch.push_back(std::move(queue.front()));queue.pop_front();}}ready.notify_all();if(batch.empty())continue;require(std::filesystem::space(std::filesystem::path(argv[3]).parent_path()).available>=32ull*1024*1024*1024,"32 GiB disk reserve");auto start=Clock::now();sql(d,"BEGIN IMMEDIATE");try{for(auto&f:batch)apply(d,f,allowed);St s(d,"UPDATE state SET revision=revision+1,updated=? WHERE id=1");s.integer(1,ms());s.done();sql(d,"COMMIT");}catch(...){sql(d,"ROLLBACK");throw;}maxCommit=std::max(maxCommit,std::chrono::duration<double,std::milli>(Clock::now()-start).count());if(Clock::now()-report>std::chrono::seconds(10)){std::cout<<J{{"at",ms()},{"frames",frames.load()},{"accepted",accepted.load()},{"rejected",invalid.load()},{"reconnects",reconnects.load()},{"maxBatchCommitMs",maxCommit}}<<std::endl;report=Clock::now();maxCommit=0;}}
run=false;ready.notify_all();for(auto&t:threads)t.join();sqlite3_close(d);curl_global_cleanup();return 0;
}catch(const std::exception&e){run=false;ready.notify_all();for(auto&t:threads)if(t.joinable())t.join();if(d)sqlite3_close(d);std::cerr<<"hyperliquid_fatal: "<<e.what()<<std::endl;return 1;}}
